const cfg = $('Configuração').first().json;
const hoje = DateTime.now().setZone('America/Sao_Paulo');
const base = {
  dataDisponibilizacaoInicio: hoje.minus({ days: Number(cfg.diasRetroativos || 5) }).toISODate(),
  dataDisponibilizacaoFim: hoje.toISODate(),
  itensPorPagina: 100,
};

const consultas = [];
for (const oab of cfg.oabs || []) {
  const numero = String(oab.numero || '').replace(/\D/g, '');
  if (!numero) continue;
  consultas.push({ json: { origem: 'OAB ' + numero + '/' + oab.uf, query: { ...base, numeroOab: numero, ufOab: String(oab.uf || '').toUpperCase() } } });
}
for (const p of cfg.processos || []) {
  const numero = String(p).replace(/\D/g, '');
  if (numero.length !== 20) continue;
  consultas.push({ json: { origem: 'Processo ' + p, query: { ...base, numeroProcesso: numero } } });
}

if (!consultas.length) {
  throw new Error('Configure ao menos uma OAB ou um número de processo (20 dígitos) no nó "Configuração".');
}
return consultas;

const cfg = $('Configuração').first().json;
const TZ = 'America/Sao_Paulo';
const PRAZO_PADRAO = Number(cfg.prazoPadraoDias || 15);
const extras = new Set((cfg.feriadosExtras || []).map(String));

function pascoa(y) {
  const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
  const mes = Math.floor((h + l - 7 * m + 114) / 31), dia = ((h + l - 7 * m + 114) % 31) + 1;
  return DateTime.fromObject({ year: y, month: mes, day: dia }, { zone: TZ });
}

const cacheFeriados = {};
function feriadosNacionais(y) {
  if (cacheFeriados[y]) return cacheFeriados[y];
  const s = new Set(['01-01', '04-21', '05-01', '09-07', '10-12', '11-02', '11-15', '11-20', '12-25'].map(md => y + '-' + md));
  s.add(pascoa(y).minus({ days: 2 }).toISODate());
  cacheFeriados[y] = s;
  return s;
}

function ehDiaUtil(d) {
  if (d.weekday > 5) return false;
  const iso = d.toISODate();
  if (feriadosNacionais(d.year).has(iso) || extras.has(iso)) return false;
  if (cfg.considerarRecessoForense !== false) {
    const md = d.toFormat('MM-dd');
    if (md >= '12-20' || md <= '01-20') return false;
  }
  return true;
}
function proximoDiaUtil(d) {
  let x = d.plus({ days: 1 });
  while (!ehDiaUtil(x)) x = x.plus({ days: 1 });
  return x;
}
function calcularVencimento(inicio, dias) {
  let x = inicio;
  for (let c = 1; c < dias; c++) x = proximoDiaUtil(x);
  return x;
}

const POR_EXTENSO = { um: 1, uma: 1, dois: 2, duas: 2, 'três': 3, tres: 3, quatro: 4, cinco: 5, seis: 6, sete: 7, oito: 8, nove: 9, dez: 10, onze: 11, doze: 12, quinze: 15, vinte: 20, trinta: 30, quarenta: 40, sessenta: 60, noventa: 90 };

function detectarPrazo(texto) {
  const t = texto.toLowerCase();
  let m = t.match(/(?:prazo|em|dentro de)\s+(?:\S+\s+){0,2}?(?:de\s+)?(\d{1,3})\s*(?:\([^)]{0,40}\))?\s*dias?\b/);
  if (m && +m[1] >= 1 && +m[1] <= 365) return { dias: +m[1], origem: 'Identificado no texto' };
  m = t.match(/(?:prazo|em|dentro de)\s+(?:\S+\s+){0,2}?(?:de\s+)?(\S+)\s+dias?\b/);
  if (m && POR_EXTENSO[m[1]]) return { dias: POR_EXTENSO[m[1]], origem: 'Identificado no texto' };
  m = t.match(/(\d{1,3})\s*(?:\([^)]{0,40}\))?\s*horas/);
  if (m) return { dias: Math.max(1, Math.ceil(+m[1] / 24)), origem: 'Prazo em horas (' + m[1] + 'h) - CONFERIR' };
  return { dias: PRAZO_PADRAO, origem: 'Padrão (' + PRAZO_PADRAO + ' dias) - não identificado no texto' };
}

function parseData(v) {
  if (!v) return null;
  const s = String(v).slice(0, 10);
  const d = /^\d{4}-\d{2}-\d{2}$/.test(s) ? DateTime.fromISO(s, { zone: TZ }) : DateTime.fromFormat(s, 'dd/MM/yyyy', { zone: TZ });
  return d.isValid ? d : null;
}
const DIACRITICOS = { acute: '\u0301', grave: '\u0300', tilde: '\u0303', circ: '\u0302', cedil: '\u0327', uml: '\u0308' };
const ENTIDADES = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", ordm: 'º', ordf: 'ª', sect: '§', deg: '°', ndash: '-', mdash: '-', laquo: '«', raquo: '»', ldquo: '"', rdquo: '"', lsquo: "'", rsquo: "'", hellip: '...' };
function limparHtml(s) {
  return String(s || '')
    .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&([A-Za-z])(acute|grave|tilde|circ|cedil|uml);/g, (_, l, d) => (l + DIACRITICOS[d]).normalize('NFC'))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(+n))
    .replace(/&([a-z]+);/gi, (m, e) => ENTIDADES[e.toLowerCase()] ?? m)
    .replace(/\s+/g, ' ')
    .trim();
}
const fmt = d => (d ? d.toFormat('dd/MM/yyyy') : '');

const porId = new Map();
for (const item of $input.all()) {
  const lista = Array.isArray(item.json.items) ? item.json.items : [];
  for (const c of lista) {
    const id = String(c.id ?? c.hash ?? '');
    if (id && !porId.has(id)) porId.set(id, c);
  }
}

const agora = DateTime.now().setZone(TZ);
const saida = [];
for (const [id, c] of porId) {
  const teor = limparHtml(c.texto);
  const prazo = detectarPrazo(teor);
  const disponibilizacao = parseData(c.data_disponibilizacao || c.datadisponibilizacao || c.dataDisponibilizacao);
  const publicacao = disponibilizacao ? proximoDiaUtil(disponibilizacao) : null;
  const inicio = publicacao ? proximoDiaUtil(publicacao) : null;
  const vencimento = inicio ? calcularVencimento(inicio, prazo.dias) : null;
  const partes = (c.destinatarios || []).map(x => x.nome + (x.polo ? ' (' + x.polo + ')' : '')).join('; ');

  saida.push({
    json: {
      'ID': id,
      'Vencimento': fmt(vencimento),
      'Status': vencimento ? 'Pendente' : 'Conferir',
      'Processo': c.numeroprocessocommascara || c.numero_processo || '',
      'Tribunal': c.siglaTribunal || '',
      'Orgao': c.nomeOrgao || '',
      'Tipo': [c.tipoComunicacao, c.tipoDocumento].filter(Boolean).join(' / '),
      'Classe': c.nomeClasse || '',
      'Partes': partes,
      'Prazo (dias)': prazo.dias,
      'Origem do prazo': prazo.origem,
      'Disponibilizacao': fmt(disponibilizacao),
      'Publicacao': fmt(publicacao),
      'Inicio do prazo': fmt(inicio),
      'Link': c.link || 'https://comunica.pje.jus.br/',
      'Teor': teor.slice(0, 3000),
      'Capturado em': agora.toFormat('dd/MM/yyyy HH:mm'),
      _vencISO: vencimento ? vencimento.toISODate() : agora.toISODate(),
      _vencFimISO: (vencimento || agora).plus({ days: 1 }).toISODate(),
    },
  });
}

saida.sort((a, b) => a.json._vencISO.localeCompare(b.json._vencISO));
return saida.length ? saida : [{ json: { _vazio: true } }];

const jaSalvos = new Set(
  $input.all().map(i => String(i.json.ID ?? '')).filter(Boolean)
);
const publicacoes = $('Processar Publicações').all().filter(i => !i.json._vazio);
const novas = publicacoes.filter(i => !jaSalvos.has(String(i.json.ID)));

return novas.length ? novas : [{ json: { _vazio: true } }];

return $input.all().map(i => {
  const linha = {};
  for (const [k, v] of Object.entries(i.json)) {
    if (!k.startsWith('_')) linha[k] = v;
  }
  return { json: linha };
});

